#!/usr/bin/env python3
"""Fill an HWPX (zip) template using JSON data.

Contract for this task:
- Replace all {{key}} placeholders in section XML files.
- Handle placeholders split across multiple <hp:t> nodes by merging.
- Append month spans to phase lines (1/2/3단계 ... date ranges).
- Remove <hp:linesegarray> from any paragraph (<hp:p>) whose visible text changed.
- Preserve namespaces (avoid ns0 prefix pollution) by registering namespaces found in the original XML.
- Re-zip extracted directory to /root/project_proposal_ready.hwpx with correct relative paths.
"""

from __future__ import annotations

import json
import os
import re
import sys
import zipfile
from dataclasses import dataclass
from pathlib import Path
import xml.etree.ElementTree as ET

JSON_PATH = Path("/root/project_proposal.json")
EXTRACTED_DIR = Path("/root/hwpx_work/template_extracted")
OUT_HWPX = Path("/root/project_proposal_ready.hwpx")


CURRENCY_PREFIXES = {"₩", "$", "€", "¥", "£"}


def load_json(path: Path) -> dict:
    with path.open("r", encoding="utf-8") as f:
        return json.load(f)


def sanitize_value(v):
    """Strip commas from currency values while preserving the leading symbol."""
    if isinstance(v, str) and v and v[0] in CURRENCY_PREFIXES and "," in v:
        # Keep only comma removal; do not touch other punctuation.
        return v[0] + v[1:].replace(",", "")
    return v


XMLNS_RE = re.compile(r"\sxmlns(?::(?P<pfx>[A-Za-z_][\w.-]*))?=\"(?P<uri>[^\"]+)\"")


def register_namespaces_from_xml_text(xml_text: str) -> dict:
    """Register namespaces as they appear in the original XML.

    Returns a prefix->uri mapping ('' for default namespace).
    """
    nsmap: dict[str, str] = {}
    for m in XMLNS_RE.finditer(xml_text):
        pfx = m.group("pfx") or ""
        uri = m.group("uri")
        # ET.register_namespace expects prefix '' for default namespace.
        if pfx not in nsmap:
            nsmap[pfx] = uri
            ET.register_namespace(pfx, uri)
    return nsmap


PLACEHOLDER_RE = re.compile(r"{{\s*([^{}]+?)\s*}}")


@dataclass
class TextRun:
    elem: ET.Element
    start: int
    end: int


def _collect_hp_t_elems(p_elem: ET.Element, hp_uri: str) -> list[ET.Element]:
    t_tag = f"{{{hp_uri}}}t"
    # Walk in document order within paragraph.
    return [e for e in p_elem.iter() if e.tag == t_tag]


def _concat_text(elems: list[ET.Element]) -> str:
    return "".join([(e.text or "") for e in elems])


def _compute_text_ranges(t_elems: list[ET.Element]) -> list[TextRun]:
    ranges: list[TextRun] = []
    pos = 0
    for e in t_elems:
        s = pos
        pos += len(e.text or "")
        ranges.append(TextRun(e, s, pos))
    return ranges


def _placeholder_spans_multiple_nodes(full_text: str, ranges: list[TextRun]) -> bool:
    for m in PLACEHOLDER_RE.finditer(full_text):
        ms, me = m.span()
        containing = [r for r in ranges if r.start <= ms and me <= r.end]
        if not containing:
            # Spans across at least two nodes.
            return True
    return False


def _merge_t_nodes(p_elem: ET.Element, t_elems: list[ET.Element], hp_uri: str) -> None:
    """Merge all paragraph text into the first <hp:t>, remove the rest."""
    if not t_elems:
        return
    full_text = _concat_text(t_elems)
    t_elems[0].text = full_text

    t_tag = f"{{{hp_uri}}}t"
    # Remove remaining <hp:t> elements. Must remove from their direct parent.
    for t in t_elems[1:]:
        parent = _find_parent(p_elem, t)
        if parent is not None:
            parent.remove(t)

    # Also remove any now-empty <hp:run> elements (optional but keeps XML tidy).
    run_tag = f"{{{hp_uri}}}run"
    for run in list(p_elem.iter(run_tag)):
        if len(list(run)) == 0 and (run.text is None or run.text.strip() == ""):
            parent = _find_parent(p_elem, run)
            if parent is not None:
                parent.remove(run)

    # Ensure only one <hp:t> remains with the combined text (common expectation).
    # If the first <hp:t> was removed due to an unexpected structure, re-add it.
    # (Should not happen in our templates, but defensive.)
    if not any(e.tag == t_tag for e in p_elem.iter()):
        run = ET.SubElement(p_elem, run_tag)
        t = ET.SubElement(run, t_tag)
        t.text = full_text


def _find_parent(root: ET.Element, child: ET.Element) -> ET.Element | None:
    for p in root.iter():
        for c in list(p):
            if c is child:
                return p
    return None


def _replace_placeholders_in_text(text: str, data: dict) -> tuple[str, bool]:
    changed = False

    def repl(m: re.Match) -> str:
        nonlocal changed
        key = m.group(1)
        if key in data:
            val = sanitize_value(data[key])
            changed = True
            return str(val)
        return m.group(0)

    new_text = PLACEHOLDER_RE.sub(repl, text)
    return new_text, changed


DATE_RE = re.compile(r"(?P<y>\d{4})[.-](?P<m>\d{1,2})")


def _month_span_inclusive(start_y: int, start_m: int, end_y: int, end_m: int) -> int:
    return (end_y - start_y) * 12 + (end_m - start_m) + 1


def _append_phase_months(text: str) -> tuple[str, bool]:
    """Append ' (N개월)' to phase lines that include a date or date range.

    Supports strings like:
      '1단계: ... (2026-08 ~ 2026-10)'
      '2단계: ... (2026.10 ~ 2026.12)'
      '3단계: ... (2027-01)'

    Only appends if a suffix like '(N개월)' is not already present.
    """
    if "개월" in text:
        return text, False

    # Must be a phase line.
    if not ("1단계" in text or "2단계" in text or "3단계" in text or "단계1" in text or "단계2" in text or "단계3" in text):
        return text, False

    # Extract the area where dates usually live (inside parentheses), else scan whole text.
    m_paren = re.search(r"\(([^)]*)\)", text)
    date_area = m_paren.group(1) if m_paren else text

    dates = [(int(m.group("y")), int(m.group("m"))) for m in DATE_RE.finditer(date_area)]
    if not dates:
        return text, False

    if len(dates) >= 2:
        (sy, sm), (ey, em) = dates[0], dates[1]
        months = _month_span_inclusive(sy, sm, ey, em)
    else:
        months = 1

    return f"{text} ({months}개월)", True


def _remove_linesegarray(p_elem: ET.Element, hp_uri: str) -> bool:
    removed = False
    ls_tag = f"{{{hp_uri}}}linesegarray"
    for child in list(p_elem):
        if child.tag == ls_tag:
            p_elem.remove(child)
            removed = True
    return removed


def process_section_xml(xml_path: Path, data: dict) -> None:
    xml_text = xml_path.read_text(encoding="utf-8")
    nsmap = register_namespaces_from_xml_text(xml_text)

    hp_uri = nsmap.get("hp")
    if not hp_uri:
        raise RuntimeError(f"Missing 'hp' namespace in {xml_path}")

    tree = ET.ElementTree(ET.fromstring(xml_text))
    root = tree.getroot()

    p_tag = f"{{{hp_uri}}}p"

    placeholders_remaining = []

    for p in root.iter(p_tag):
        # Collect text nodes.
        t_elems = _collect_hp_t_elems(p, hp_uri)
        if not t_elems:
            continue

        before_text = _concat_text(t_elems)

        # Detect and merge split placeholders.
        ranges = _compute_text_ranges(t_elems)
        full_text = before_text
        if "{{" in full_text and "}}" in full_text and _placeholder_spans_multiple_nodes(full_text, ranges):
            _merge_t_nodes(p, t_elems, hp_uri)
            # Re-collect after merge.
            t_elems = _collect_hp_t_elems(p, hp_uri)

        text_changed = False

        # Replace placeholders (per node; merged case will have just one node).
        for t in t_elems:
            orig = t.text or ""
            new, changed = _replace_placeholders_in_text(orig, data)
            if changed:
                t.text = new
                text_changed = True

        # Phase month suffix: operate on the concatenated paragraph text.
        # If there are multiple <hp:t>, update the first and keep the rest as-is.
        t_elems = _collect_hp_t_elems(p, hp_uri)
        after_repl_text = _concat_text(t_elems)
        after_phase_text, phase_changed = _append_phase_months(after_repl_text)
        if phase_changed:
            # To avoid splitting the new suffix across nodes, merge everything into one.
            _merge_t_nodes(p, t_elems, hp_uri)
            t_elems = _collect_hp_t_elems(p, hp_uri)
            if t_elems:
                t_elems[0].text = after_phase_text
            text_changed = True

        # Remove stale layout cache if paragraph text changed.
        if text_changed:
            _remove_linesegarray(p, hp_uri)

        # Track remaining placeholders.
        final_text = _concat_text(_collect_hp_t_elems(p, hp_uri))
        if "{{" in final_text:
            placeholders_remaining.append((p.get("id"), final_text))

    if placeholders_remaining:
        for pid, t in placeholders_remaining:
            print(f"ERROR: placeholder remains in {xml_path} paragraph id={pid}: {t}", file=sys.stderr)
        raise SystemExit(1)

    tree.write(xml_path, encoding="utf-8", xml_declaration=True)


def rezip_directory(src_dir: Path, out_zip: Path) -> None:
    if out_zip.exists():
        out_zip.unlink()
    with zipfile.ZipFile(out_zip, "w", compression=zipfile.ZIP_DEFLATED) as z:
        for path in sorted(src_dir.rglob("*")):
            if path.is_dir():
                continue
            arcname = path.relative_to(src_dir).as_posix()
            z.write(path, arcname)


def main() -> int:
    data_raw = load_json(JSON_PATH)
    # Pre-sanitize values (currency commas) so replacements are consistent.
    data = {k: sanitize_value(v) for k, v in data_raw.items()}

    if not EXTRACTED_DIR.exists():
        raise RuntimeError(f"Extracted dir not found: {EXTRACTED_DIR}")

    xml_paths = sorted((EXTRACTED_DIR / "Contents").glob("section*.xml"))
    if not xml_paths:
        raise RuntimeError("No section XML files found under Contents/")

    for xp in xml_paths:
        process_section_xml(xp, data)

    rezip_directory(EXTRACTED_DIR, OUT_HWPX)

    # Basic validity: ensure it's a readable zip.
    with zipfile.ZipFile(OUT_HWPX, "r") as z:
        bad = z.testzip()
        if bad is not None:
            print(f"ERROR: zip integrity check failed at {bad}", file=sys.stderr)
            return 2

    print(f"Wrote: {OUT_HWPX}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

